/* Exam 2 instructor-derived practice: original source answers preserved in sourceOriginal when medical revision required. */
window.VPQ_PHARM_EXAM2_PDF_PRACTICE=[{"id":"exam2-pdf-practice-001","lecture":"Lecture 10","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #1","q":"A newly diagnosed obese diabetic cat is clinically stable and eating. What is the most appropriate way to frame the treatment goal?","options":["Remission is guaranteed after starting a long-acting insulin","Restore clinical wellbeing and safe glycemic control while aiming for possible remission if beta-cell function recovers","Avoid treating because feline diabetes is always transient","Remission requires withholding insulin until glucotoxicity resolves"],"answer":1,"why":"Feline remission can occur when glucotoxicity and insulin resistance improve and enough beta-cell function remains. It is a potential outcome, not an assured or sole treatment goal.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":1,"sourceOriginal":{"question":"A 9-year-old obese cat is newly diagnosed with diabetes. What is the most likely type and the primary treatment goal?","options":["Type 2; eliminate clinical signs only","Type 2; remission","Type 1; prevent DKA only","Type 1; remission"],"answer":1,"rationale":"Cats are usually Type 2 (obesity-desensitized receptors); remission is the primary goal."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-002","lecture":"Lecture 10","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #2","q":"Which insulin is a first-choice drug to start a diabetic dog?","options":["Detemir","NPH or Vetsulin","Glargine","Regular insulin"],"answer":1,"why":"Intermediate-acting insulins (NPH, Vetsulin) start dogs.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":2},{"id":"exam2-pdf-practice-003","lecture":"Lecture 10","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #3","q":"An owner is preparing U-40 porcine lente insulin (Vetsulin) and another cat receives clear glargine. Which handling distinction is appropriate?","options":["Shake both preparations vigorously to activate the insulin","Gently roll clear glargine until it becomes milky before injection","Resuspend Vetsulin according to its product instructions; do not shake or mix clear glargine as if it were a suspension","Mix Vetsulin and glargine to ensure comparable duration"],"answer":2,"why":"Vetsulin is a suspension requiring thorough manufacturer-directed resuspension. Glargine is a clear solution with pH-dependent depot formation and should not be shaken to resuspend particles or mixed with other insulins.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":3,"sourceOriginal":{"question":"Which preparation must be shaken vigorously before use, unlike the others, which are rolled?","options":["PZI","NPH","Vetsulin","Glargine"],"answer":2,"rationale":"Vetsulin is shaken; all others are rolled."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-004","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #4","q":"A dehydrated dog with DKA needs insulin therapy. Which approach accounts for unstable perfusion and electrolyte shifts?","options":["Give a depot insulin before restoring perfusion because a slow onset is safer","Use monitored short-acting regular insulin in a hospital protocol after addressing fluids and potassium; IV CRI is often chosen","Use U-40 lente insulin IV because zinc protects against hypokalemia","Withhold all potassium monitoring because insulin prevents electrolyte losses"],"answer":1,"why":"Regular insulin can be titrated in monitored critical care. Profound hypoperfusion can impair SQ uptake; that context does not make SQ regular insulin universally prohibited. Insulin drives potassium intracellularly, creating hypokalemia risk.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":4,"sourceOriginal":{"question":"A dehydrated diabetic dog is in DKA. Which insulin and route?","options":["Glargine SQ","Regular insulin as an IV constant-rate infusion or IM","NPH SQ","Vetsulin SQ"],"answer":1,"rationale":"Regular insulin has no excipients; IV CRI or IM, never SQ in a dehydrated patient."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-005","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #5","q":"Why must glargine only be diluted with the manufacturer's diluent?","options":["It is only soluble in oil","A wrong-pH diluent disrupts its precipitation at the injection site and ruins the slow release","Dilution makes it crystalline","Saline destroys the peptide"],"answer":1,"why":"It is soluble at pH 4 and precipitates at tissue pH 7.4; the wrong diluent ruins that.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":5},{"id":"exam2-pdf-practice-006","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #6","q":"Why is insulin detemir dosed particularly cautiously when used in dogs?","options":["Some dogs are highly sensitive to detemir, increasing hypoglycemia risk even at comparatively small doses","Detemir must always be given IV because it lacks a subcutaneous depot effect","All human detemir vials contain four times the concentration of standard U-100 insulin","Detemir is inactive at canine insulin receptors and therefore requires a universal quadruple dose"],"answer":0,"why":"Detemir's fatty-acid modification promotes albumin binding and prolonged effect. Individual dogs can be especially sensitive; the lecture's explanation about a universal fourfold human-product concentration is not reliable.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":6,"sourceOriginal":{"question":"What is the caveat with detemir in dogs?","options":["The human product is 4× concentrated because of low human-receptor affinity, but its canine-receptor affinity is normal, so hypoglycemic crises can occur","It can only be given IV","Poor affinity for the canine receptor causes hyperglycemia","Myristic acid is toxic to dogs"],"answer":0,"rationale":"Human product is 4× concentrated, but canine receptor affinity is normal, so hypoglycemia risk."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-007","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #7","q":"A diabetic dog on porcine lente insulin has fluctuating glucose curves and suspected rebound hyperglycemia. What is the next clinically defensible step?","options":["Increase the insulin dose immediately because all hyperglycemia proves underdosing","Evaluate CGM/curves, timing, food intake and any true hypoglycemic nadir before adjusting insulin formulation or dose","Switch automatically to PZI at precisely the same number of units","Stop insulin permanently because all rebound hyperglycemia indicates remission"],"answer":1,"why":"Somogyi rebound is challenging to confirm and should not be assumed from a high spot glucose reading. Document the actual glucose nadir and reassess regimen before a patient-specific dose/formulation change. COURSE ORIGINAL: switch to PZI at the same number of units.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":7,"sourceOriginal":{"question":"A diabetic dog on Vetsulin shows the Somogyi effect. What is the next insulin choice?","options":["Humulin 70/30","PZI at the same number of units","Regular insulin","Lispro"],"answer":1,"rationale":"A longer-duration insulin (PZI) at the same units; the dose may be right but released too fast. ⚠ SOURCE REVIEW: The source's insulin-switching instruction is an exam note, not a patient-specific dosing recommendation."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-008","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #8","q":"How does renal disease affect insulin therapy?","options":["It shortens the duration of action","It has no effect","It causes anti-insulin antibodies","The kidneys clear insulin, so exogenous insulin lasts longer"],"answer":3,"why":"Kidneys clear insulin, so duration lengthens.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":8},{"id":"exam2-pdf-practice-009","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #9","q":"A diabetic cat remains poorly regulated despite escalating insulin needs and develops broad facial features and organ enlargement. Which comorbidity merits investigation?","options":["Hypoadrenocorticism","Hypothyroidism","Hypersomatotropism (acromegaly) causing insulin resistance","Diabetes insipidus causing isolated hypoglycemia"],"answer":2,"why":"Growth hormone excess can produce marked insulin resistance in cats. Do not memorize any single high daily unit number as a diagnostic threshold; endocrine testing and patient context matter.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":9,"sourceOriginal":{"question":"A diabetic cat needs up to 40 U of insulin and has sporadic sudden hypoglycemia. What is the likely underlying disease?","options":["Addison's disease","Hyperthyroidism","Acromegaly","Hypothyroidism"],"answer":2,"rationale":"Acromegaly: somatotropin is diabetogenic, pulsatile, and needs up to 40 U."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-010","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #10","q":"Streptozotocin is used to treat which condition?","options":["Equine metabolic syndrome","Fat cow ketosis","DKA","Insulinoma"],"answer":3,"why":"Streptozotocin kills islet cells (via Glut2) and treats insulinoma.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":10},{"id":"exam2-pdf-practice-011","lecture":"Lecture 11","sourceGroup":"Lecture 10–11","topic":"Exam 2 PDF practice · #11","q":"Which non-insulin drugs block the K-ATP channel in beta cells and are used in cats whose owners refuse injections?","options":["Bexagliflozin","Glipizide or glyburide","Metformin","Exenatide"],"answer":1,"why":"Sulfonylureas block the K-ATP channel so beta cells release insulin.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":11},{"id":"exam2-pdf-practice-012","lecture":"Lecture 12","sourceGroup":"Lecture 12","topic":"Exam 2 PDF practice · #12","q":"Which drug inhibits thyroperoxidase?","options":["Perchlorate","Methimazole","Levothyroxine","Propranolol"],"answer":1,"why":"Methimazole inhibits thyroperoxidase (perchlorate inhibits NIS).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":12},{"id":"exam2-pdf-practice-013","lecture":"Lecture 12","sourceGroup":"Lecture 12","topic":"Exam 2 PDF practice · #13","q":"Which of these does NOT cause pseudohypothyroidism?","options":["Phenobarbital","Levothyroxine","Sulfonamide antibiotics","Glucocorticoids"],"answer":1,"why":"Levothyroxine is the treatment, not a cause.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":13},{"id":"exam2-pdf-practice-014","lecture":"Lecture 12","sourceGroup":"Lecture 12","topic":"Exam 2 PDF practice · #14","q":"What physiologic and clinical considerations explain why levothyroxine (T4) is preferred over routine liothyronine (T3) for hypothyroid dogs?","options":["T4 can be converted to T3 in tissues and permits physiologic thyroid hormone regulation; both hormones contribute to negative feedback","T3 has no negative feedback action at hypothalamus or pituitary","T3 contains no iodine and cannot bind nuclear thyroid receptors","T4 provides thyroid hormone effects without conversion or receptor signaling"],"answer":0,"why":"Levothyroxine provides T4 for peripheral conversion and relatively physiologic replacement. Both T3 and T4 participate in feedback regulation; the original slide claim that T3 has no negative feedback should not be taught as fact.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":14,"sourceOriginal":{"question":"Why is T4 (not T3) used to treat hypothyroid dogs?","options":["T4 gives negative feedback at the hypothalamus and pituitary; T3 does not","T4 is only for cats","T3 lacks iodine","T3 is not absorbed orally"],"answer":0,"rationale":"T4 gives negative feedback on the hypothalamus and pituitary; T3 does not. ⚠ SOURCE REVIEW: The T3-vs-T4 feedback explanation may be oversimplified; verify with endocrine physiology resources."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-015","lecture":"Lecture 12","sourceGroup":"Lecture 12","topic":"Exam 2 PDF practice · #15","q":"What must happen before I¹³¹ treatment of a hyperthyroid cat?","options":["Feed Y/D during the I¹³¹ treatment","Start T4","Do a thyroidectomy","Stabilize on methimazole, check metabolic, CV and renal function, and stop it 10–14 days before"],"answer":3,"why":"Stabilize first, check metabolic, CV and renal function, and stop methimazole and Y/D 10–14 days before.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":15},{"id":"exam2-pdf-practice-016","lecture":"Lecture 12","sourceGroup":"Lecture 12","topic":"Exam 2 PDF practice · #16","q":"How are milk fever treated and prevented?","options":["IV calcium borogluconate; anionic salts in the dry period","Oral calcium; a high-calcium dry-cow diet","IV glucose; a high-calcium dry-cow diet","Tripelennamine only"],"answer":0,"why":"IV calcium borogluconate treats; anionic salts in the dry period prevent.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":16},{"id":"exam2-pdf-practice-017","lecture":"Lecture 12","sourceGroup":"Lecture 12","topic":"Exam 2 PDF practice · #17","q":"What is the treatment for hypoparathyroidism after thyroidectomy?","options":["Methimazole","PTU","Oral calcium (lactate or carbonate) plus calcitriol","Levothyroxine"],"answer":2,"why":"Oral calcium plus calcitriol.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":17},{"id":"exam2-pdf-practice-018","lecture":"Lecture 12","sourceGroup":"Lecture 12","topic":"Exam 2 PDF practice · #18","q":"Perchlorate causes hypothyroidism by inhibiting what?","options":["Pendrin","The TSH receptor","Thyroperoxidase","NIS (the Na⁺-iodide symporter)"],"answer":3,"why":"Perchlorate blocks the Na⁺-iodide symporter.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":18},{"id":"exam2-pdf-practice-019","lecture":"Lecture 13","sourceGroup":"Lecture 13","topic":"Exam 2 PDF practice · #19","q":"To prevent urination, which receptors do you target?","options":["Activate nicotinic, inhibit α1","Activate muscarinic, inhibit α1","Activate α1, inhibit muscarinic","Activate β2, inhibit nicotinic"],"answer":2,"why":"Activate α1 (SNS) and inhibit the muscarinic receptor (PNS).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":19},{"id":"exam2-pdf-practice-020","lecture":"Lecture 13","sourceGroup":"Lecture 13","topic":"Exam 2 PDF practice · #20","q":"What is the MOA of phenylpropanolamine?","options":["Muscarinic antagonist","Selective α1 antagonist","Non-selective α1 and β1 agonist","Muscarinic agonist"],"answer":2,"why":"Phenylpropanolamine is a non-selective α1 and β1 agonist (some CV effects).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":20},{"id":"exam2-pdf-practice-021","lecture":"Lecture 13","sourceGroup":"Lecture 13","topic":"Exam 2 PDF practice · #21","q":"Which muscarinic agonist promotes urination but is contraindicated after urethral obstruction?","options":["Oxybutynin","Tamsulosin","Bethanechol","Prazosin"],"answer":2,"why":"Bethanechol is a muscarinic agonist; avoid with a compromised bladder wall or past obstruction.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":21},{"id":"exam2-pdf-practice-022","lecture":"Lecture 13","sourceGroup":"Lecture 13","topic":"Exam 2 PDF practice · #22","q":"Which selective α1 antagonist treats urethrospasm from urethritis or urethroliths?","options":["Prazosin","Bethanechol","Phenoxybenzamine","Tamsulosin"],"answer":3,"why":"Tamsulosin is the selective α1 antagonist for urethrospasm.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":22},{"id":"exam2-pdf-practice-023","lecture":"Lecture 13","sourceGroup":"Lecture 13","topic":"Exam 2 PDF practice · #23","q":"Which statement about atropine in the eye is true?","options":["It is safe at any dose in horses","It is contraindicated in glaucoma and KCS; use ointment in cats","It is short-acting and used for routine exams","It is a miotic"],"answer":1,"why":"Contraindicated in glaucoma and KCS; ointment in cats because drops cause hypersalivation.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":23},{"id":"exam2-pdf-practice-024","lecture":"Lecture 13","sourceGroup":"Lecture 13","topic":"Exam 2 PDF practice · #24","q":"How is organophosphate toxicosis treated?","options":["Atropine alone","Pralidoxime alone","Neostigmine","Atropine plus pralidoxime within 24 hours"],"answer":3,"why":"Atropine blocks muscarinic signs; pralidoxime within 24 h, always with atropine.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":24},{"id":"exam2-pdf-practice-025","lecture":"Lecture 13","sourceGroup":"Lecture 13","topic":"Exam 2 PDF practice · #25","q":"What does succinylcholine do?","options":["Blocks the muscarinic receptor","Inhibits AChE","Activates the α1 receptor","Activates the nicotinic receptor at the NMJ and is not broken down by AChE, causing flaccid paralysis"],"answer":3,"why":"It activates the NMJ nicotinic receptor and is not broken down by AChE.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":25},{"id":"exam2-pdf-practice-026","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #26","q":"What is the MOA of digoxin?","options":["Inhibits the Na⁺/K⁺ ATPase, so Na⁺ rises, the exchanger runs in reverse, and Ca²⁺ rises","Troponin C sensitization","PDE3 inhibition","β1 agonism"],"answer":0,"why":"Na⁺/K⁺ ATPase inhibition raises Na⁺, reverses the Na⁺/Ca²⁺ exchanger, and raises Ca²⁺.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":26},{"id":"exam2-pdf-practice-027","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #27","q":"Which anti-CHF drug is also a vasodilator and is approved only in dogs?","options":["Pimobendan","Digoxin","Dobutamine","Amrinone"],"answer":0,"why":"Pimobendan is an inodilator, dogs only.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":27},{"id":"exam2-pdf-practice-028","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #28","q":"Digoxin toxicity is more likely when the patient is:","options":["Hyperkalemic","Hypokalemic","Hypercalcemic","Hypernatremic"],"answer":1,"why":"Hypokalemia increases digoxin toxicity.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":28},{"id":"exam2-pdf-practice-029","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #29","q":"Which drug treats an arrhythmia caused by feline hyperthyroidism?","options":["Propranolol","Digoxin","Lidocaine","Amlodipine"],"answer":0,"why":"Propranolol, a non-selective β blocker.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":29},{"id":"exam2-pdf-practice-030","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #30","q":"Which anti-arrhythmic can cause corneal deposits?","options":["Mexiletine","Lidocaine","Amiodarone","Procainamide"],"answer":2,"why":"Amiodarone (also pulmonary fibrosis; avoid in bradycardia).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":30},{"id":"exam2-pdf-practice-031","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #31","q":"What is the preferred drug for long-term oral treatment of V-tach?","options":["Amlodipine","Lidocaine","Hydralazine","Procainamide"],"answer":3,"why":"Procainamide (halve the dose with renal disease).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":31},{"id":"exam2-pdf-practice-032","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #32","q":"Why is hydralazine reserved for emergencies?","options":["It causes bradycardia","It causes hyperkalemia","It can cause so much hypotension that the baroreflex triggers tachycardia with extended use","It causes corneal deposits"],"answer":2,"why":"Baroreflex tachycardia from marked hypotension.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":32},{"id":"exam2-pdf-practice-033","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #33","q":"Which drug treats pulmonary hypertension?","options":["Telmisartan","Enalapril","Dobutamine","Sildenafil"],"answer":3,"why":"Sildenafil, a PDE5 inhibitor.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":33},{"id":"exam2-pdf-practice-034","lecture":"Lecture 14","sourceGroup":"Lecture 14","topic":"Exam 2 PDF practice · #34","q":"What is the mainstay drug of cardiac resuscitation?","options":["Sodium bicarbonate","Epinephrine","Atropine","Calcium"],"answer":1,"why":"Epinephrine is the mainstay.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":34},{"id":"exam2-pdf-practice-035","lecture":"Lecture 15","sourceGroup":"Lecture 15","topic":"Exam 2 PDF practice · #35","q":"Which selective β2 agonist is used orally or parenterally for feline \"asthma\"?","options":["Ephedrine","Epinephrine","Isoproterenol","Terbutaline"],"answer":3,"why":"Terbutaline is β2-selective.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":35},{"id":"exam2-pdf-practice-036","lecture":"Lecture 15","sourceGroup":"Lecture 15","topic":"Exam 2 PDF practice · #36","q":"What is the issue with zilpaterol?","options":["It is approved for horses","It is highly toxic to horses, and it was withdrawn from cattle over health problems including lameness","It is banned only in cattle","It is non-selective for β receptors"],"answer":1,"why":"Zilpaterol is highly toxic to horses and was withdrawn from cattle.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":36},{"id":"exam2-pdf-practice-037","lecture":"Lecture 15","sourceGroup":"Lecture 15","topic":"Exam 2 PDF practice · #37","q":"How do theophylline and aminophylline bronchodilate?","options":["Muscarinic antagonism","Phosphodiesterase inhibition, so cAMP is not broken down","α1 blockade","β2 agonism"],"answer":1,"why":"PDE inhibition raises cAMP.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":37},{"id":"exam2-pdf-practice-038","lecture":"Lecture 15","sourceGroup":"Lecture 15","topic":"Exam 2 PDF practice · #38","q":"Which drug is a non-narcotic central antitussive?","options":["Hydrocodone","Butorphanol","Codeine","Dextromethorphan"],"answer":3,"why":"Dextromethorphan; codeine, hydrocodone and butorphanol are narcotic.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":38},{"id":"exam2-pdf-practice-039","lecture":"Lecture 15","sourceGroup":"Lecture 15","topic":"Exam 2 PDF practice · #39","q":"What does doxapram do?","options":["Blocks muscarinic receptors","Activates carotid body chemoreceptors to stimulate respiration; can reverse opioid respiratory depression","Suppresses cough","Breaks disulfide bonds in mucus"],"answer":1,"why":"Doxapram stimulates respiration via carotid body chemoreceptors.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":39},{"id":"exam2-pdf-practice-040","lecture":"Lecture 15","sourceGroup":"Lecture 15","topic":"Exam 2 PDF practice · #40","q":"Which antibiotic is used for respiratory infections in dogs and cats?","options":["Ceftiofur","Tulathromycin","Florfenicol","Amoxicillin plus clavulanate"],"answer":3,"why":"Amoxicillin plus clavulanate; the others are for cattle, swine and horses.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":40},{"id":"exam2-pdf-practice-041","lecture":"Lecture 15","sourceGroup":"Lecture 15","topic":"Exam 2 PDF practice · #41","q":"Why is ipratropium preferred over atropine as a bronchodilator?","options":["It is a better bronchodilator and, being poorly absorbed and not crossing the blood-brain barrier, has fewer side effects","It increases mucociliary clearance","It is a methylxanthine","It is a β2 agonist"],"answer":0,"why":"Ipratropium is poorly absorbed and does not cross the blood-brain barrier.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":41},{"id":"exam2-pdf-practice-042","lecture":"Lecture 16","sourceGroup":"Lecture 16","topic":"Exam 2 PDF practice · #42","q":"What is the MOA of furosemide?","options":["Blocks eNaC","Blocks the mineralocorticoid receptor","Blocks the Na-Cl symporter","Inhibits NKCC2 in the thick ascending limb"],"answer":3,"why":"Furosemide inhibits NKCC2.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":42},{"id":"exam2-pdf-practice-043","lecture":"Lecture 16","sourceGroup":"Lecture 16","topic":"Exam 2 PDF practice · #43","q":"What is the drug of choice for preparturient udder edema in cattle?","options":["Furosemide","Dexamethasone","Hydrochlorothiazide","Spironolactone"],"answer":0,"why":"Furosemide does not induce parturition (dexamethasone does).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":43},{"id":"exam2-pdf-practice-044","lecture":"Lecture 16","sourceGroup":"Lecture 16","topic":"Exam 2 PDF practice · #44","q":"What is the MOA of spironolactone, and why does it not waste K⁺?","options":["Inhibits NKCC2","Blocks eNaC","Blocks the mineralocorticoid receptor, so Na⁺ stays in the lumen and K⁺ is retained","Blocks carbonic anhydrase"],"answer":2,"why":"Blocking the aldosterone receptor keeps Na⁺ in the lumen and K⁺ in the body.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":44},{"id":"exam2-pdf-practice-045","lecture":"Lecture 16","sourceGroup":"Lecture 16","topic":"Exam 2 PDF practice · #45","q":"Which are adverse effects of acetazolamide?","options":["Metabolic alkalosis and hyperkalemia","Hyperkalemia and acidic urine","Ototoxicity","Metabolic acidosis, uroliths from alkaline urine, hypokalemia"],"answer":3,"why":"Carbonic anhydrase inhibitors: acidosis, uroliths, hypokalemia.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":45},{"id":"exam2-pdf-practice-046","lecture":"Lecture 16","sourceGroup":"Lecture 16","topic":"Exam 2 PDF practice · #46","q":"What is mannitol used for?","options":["Hypertension","Emergency treatment of raised intracranial or intraocular pressure","Chronic CHF","Udder edema"],"answer":1,"why":"Mannitol is an IV emergency drug for ICP or IOP.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":46},{"id":"exam2-pdf-practice-047","lecture":"Lecture 16","sourceGroup":"Lecture 16","topic":"Exam 2 PDF practice · #47","q":"Why do most diuretics cause hypokalemia?","options":["ADH is stimulated","Aldosterone is blocked","NKCC2 pumps K⁺ into the lumen","Extra Na⁺ reaching the late distal tubule is exchanged for K⁺ by eNaC"],"answer":3,"why":"eNaC swaps the extra late-tubule Na⁺ for K⁺.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":47},{"id":"exam2-pdf-practice-048","lecture":"Lecture 16","sourceGroup":"Lecture 16","topic":"Exam 2 PDF practice · #48","q":"What is the advantage of torsemide over furosemide?","options":["Shorter acting","More diuresis per mg, longer acting and smoother, though harder to dose","Less potent","It is not approved in dogs"],"answer":1,"why":"Torsemide is more potent and smoother but harder to dose.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":48},{"id":"exam2-pdf-practice-049","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #49","q":"What is the MOA of maropitant?","options":["5-HT3 antagonist","NK1 antagonist (caution with liver disease)","Muscarinic antagonist","D2 antagonist"],"answer":1,"why":"Maropitant is an NK1 antagonist.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":49},{"id":"exam2-pdf-practice-050","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #50","q":"Metoclopramide is contraindicated when vomiting is caused by:","options":["Pancreatitis","Pregnancy","Hyperthyroidism","GI obstruction"],"answer":3,"why":"All prokinetics are contraindicated with GI obstruction.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":50},{"id":"exam2-pdf-practice-051","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #51","q":"A dog with persistent vomiting despite first-line antiemetic treatment has no evidence of mechanical obstruction. Which comparison correctly identifies ondansetron's mechanism?","options":["It blocks NK1 substance-P receptors whereas maropitant blocks 5-HT3","It blocks 5-HT3 receptors involved in emetic signaling; selection depends on etiology rather than a universal potency ranking","It directly activates D2 receptors to speed stomach emptying","It irreversibly blocks H2 receptors to prevent acid reflux"],"answer":1,"why":"Ondansetron is a 5-HT3 antagonist and can be considered in refractory vomiting; maropitant blocks NK1. Calling one agent universally the most potent ignores species, cause and dose.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":51,"sourceOriginal":{"question":"Which anti-emetic is reserved for refractory or severe emesis?","options":["Apomorphine","Maropitant","Metoclopramide","Ondansetron"],"answer":3,"rationale":"Ondansetron is the most potent anti-emetic."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-052","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #52","q":"Which drug is used to induce emesis in cats?","options":["Ropinirole","Low-dose xylazine","Apomorphine","3% hydrogen peroxide"],"answer":1,"why":"Low-dose xylazine (or hydromorphone) in cats.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":52},{"id":"exam2-pdf-practice-053","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #53","q":"Why is cisapride only available compounded?","options":["It is unstable","It is controlled","The human product was withdrawn for cardiotoxicity (long QT)","It is bitter"],"answer":2,"why":"The human form was pulled for long QT.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":53},{"id":"exam2-pdf-practice-054","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #54","q":"What is the first-choice drug for GI ulcers, especially with esophagitis?","options":["Famotidine","Omeprazole or pantoprazole (a PPI)","Sucralfate","Misoprostol"],"answer":1,"why":"PPIs are first choice, especially with esophagitis.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":54},{"id":"exam2-pdf-practice-055","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #55","q":"Why must misoprostol not be used in pregnant animals?","options":["It causes hypotension","It activates the PGF2α receptor on luteal cells, causing luteolysis","It is teratogenic","It raises progesterone"],"answer":1,"why":"Misoprostol activates PGF2α receptors on the corpus luteum.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":55},{"id":"exam2-pdf-practice-056","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #56","q":"Which three antibiotics are used for IBD?","options":["Amoxicillin, enrofloxacin, doxycycline","Metronidazole, tylosin, sulfasalazine","Cephalexin, clindamycin, ampicillin","Ceftiofur, tulathromycin, florfenicol"],"answer":1,"why":"Metronidazole, tylosin, sulfasalazine.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":56},{"id":"exam2-pdf-practice-057","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #57","q":"What is the caution with bismuth salicylate?","options":["Do not use in cats (salicylate)","Contraindicated in horses","Causes constipation only","Safe in all species"],"answer":0,"why":"Not in cats because of the salicylate.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":57},{"id":"exam2-pdf-practice-058","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #58","q":"How does lactulose help hepatic encephalopathy?","options":["Acidifies the colon so NH₃ becomes NH₄⁺, which is not absorbed","Blocks NK1 receptors","Kills urease-positive bacteria","Promotes bile flow"],"answer":0,"why":"Lactulose acidifies the colon so NH₃ becomes unabsorbed NH₄⁺.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":58},{"id":"exam2-pdf-practice-059","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #59","q":"Which H2 blockers also have prokinetic (anticholinesterase) activity?","options":["Cimetidine and ranitidine","Cimetidine and famotidine","Ranitidine and nizatidine","Famotidine and nizatidine"],"answer":2,"why":"Ranitidine and nizatidine (not cimetidine or famotidine).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":59},{"id":"exam2-pdf-practice-060","lecture":"Lecture 17","sourceGroup":"Lecture 17","topic":"Exam 2 PDF practice · #60","q":"What is magnesium sulfate used for in horses?","options":["Choke","Sand impaction","As a lubricant","An osmotic agent for impactions, no more than 3 days in a row"],"answer":3,"why":"Osmotic agent; toxicity if used more than 3 days in a row.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":60},{"id":"exam2-pdf-practice-061","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #61","q":"Which drug treats severe serotonin syndrome?","options":["Atipamezole","Naloxone","Flumazenil","Cyproheptadine"],"answer":3,"why":"Cyproheptadine is the serotonin receptor blocker.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":61},{"id":"exam2-pdf-practice-062","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #62","q":"A horse has persistent cribbing despite environmental enrichment. A colleague suggests fluoxetine because cribbing must be a serotonin deficiency. Which conclusion is best?","options":["Fluoxetine is proven to cure cribbing in all horses when mixed into feed","Cribbing is always a sign of insufficient dopamine activity","Cribbing is multifactorial; investigate welfare, management and underlying causes rather than assuming an SSRI is proven routine treatment","Selegiline should be used first because all stereotypic behavior is canine cognitive dysfunction"],"answer":2,"why":"Equine stereotypies are multifactorial and management matters. The source names fluoxetine, but a categorical drug cure and a single-neurotransmitter explanation are not established general care.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":62,"sourceOriginal":{"question":"Which drug treats cribbing in horses?","options":["Fluoxetine","Buspirone","Selegiline","Clomipramine"],"answer":0,"rationale":"Fluoxetine, which can go in the feed. ⚠ SOURCE REVIEW: Behavior and aggression are multifactorial; verify categorical monoamine claims."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-063","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #63","q":"Which is the main drug for cognitive dysfunction in old dogs?","options":["Mirtazapine","Fluoxetine","Selegiline","Clomipramine"],"answer":2,"why":"Selegiline (Anipryl), as monotherapy.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":63},{"id":"exam2-pdf-practice-064","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #64","q":"Why is combination therapy of behavior drugs not recommended?","options":["Cost","Most are for horses only","Transmitter crossover causes side effects","It slows onset"],"answer":2,"why":"Transmitter crossover causes side effects.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":64},{"id":"exam2-pdf-practice-065","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #65","q":"Which is NOT a cause of serotonin syndrome?","options":["SAMe","Tryptophan","Cyproheptadine","St. John's wort"],"answer":2,"why":"Cyproheptadine treats it.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":65},{"id":"exam2-pdf-practice-066","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #66","q":"Which drug is a transdermal ear gel for appetite in cats?","options":["Trazodone","Fluoxetine","Buspirone","Mirtazapine"],"answer":3,"why":"Mirtazapine (Mirataz).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":66},{"id":"exam2-pdf-practice-067","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #67","q":"Which benzodiazepine must be injected?","options":["Diazepam","Alprazolam","Lorazepam","Midazolam"],"answer":3,"why":"Midazolam is the only BDZ that must be injected.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":67},{"id":"exam2-pdf-practice-068","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #68","q":"Why is diazepam not used long-term in cats for behavior?","options":["Pancreatitis","Fatal idiopathic hepatic necrosis","Bronchitis","Renal failure"],"answer":1,"why":"Fatal idiopathic hepatic necrosis (long-term use).","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":68},{"id":"exam2-pdf-practice-069","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #69","q":"What is a risk of flumazenil, especially with a TCA or SSRI?","options":["Seizures","Hypotension","Hepatic necrosis","Bradycardia"],"answer":0,"why":"Flumazenil can cause seizures, especially with a TCA or SSRI.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":69},{"id":"exam2-pdf-practice-070","lecture":"Lecture 18","sourceGroup":"Lecture 18","topic":"Exam 2 PDF practice · #70","q":"A patient is induced with alfaxalone before a painful procedure. Which statement best explains why additional drugs may be necessary?","options":["Alfaxalone is a mu opioid agonist providing surgical analgesia","Alfaxalone blocks NMDA receptors and does not affect GABA-A","Alfaxalone is a neuroactive steroid that enhances GABA-A-mediated hypnosis but does not reliably provide procedural analgesia","Alfaxalone is a selective alpha-2 agonist routinely reversing benzodiazepines"],"answer":2,"why":"Alfaxalone produces anesthesia via GABA-A modulation; analgesia must be addressed separately for painful interventions. The source's categorical claim about anticonvulsant efficacy is not an appropriate sole classification.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":70,"sourceOriginal":{"question":"Alfaxalone is best described as:","options":["An opioid","A glutamate antagonist","A swine sedative and poor anticonvulsant","A benzodiazepine"],"answer":2,"rationale":"Alfaxalone sedates swine but needs endogenous GABA, so it is a poor anticonvulsant."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-071","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #71","q":"What is the first-choice drug for status epilepticus?","options":["Propofol","Phenobarbital","Levetiracetam","Diazepam IV"],"answer":3,"why":"Diazepam IV every 15 min until the seizures stop.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":71},{"id":"exam2-pdf-practice-072","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #72","q":"Diazepam fails after 3–4 doses. What is next?","options":["Pentobarbital","Propofol CRI","Phenobarbital IV","Ketamine"],"answer":2,"why":"Then phenobarbital IV, then pentobarbital, then propofol CRI.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":72},{"id":"exam2-pdf-practice-073","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #73","q":"Which drug prevents seizures in epileptic cats?","options":["Phenobarbital","Primidone","Zonisamide","KBr"],"answer":0,"why":"Phenobarbital is the cat drug of choice.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":73},{"id":"exam2-pdf-practice-074","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #74","q":"What is the major side effect of KBr in cats?","options":["Bronchitis (cough)","Renal failure","Pancreatitis","Hepatic necrosis"],"answer":0,"why":"Coughing cat plus bromide equals bronchitis.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":74},{"id":"exam2-pdf-practice-075","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #75","q":"What is the major side effect in dogs on phenobarbital plus KBr?","options":["Renal failure","Pancreatitis","Bronchitis","Hepatic necrosis"],"answer":1,"why":"Pancreatitis risk with phenobarbital plus KBr.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":75},{"id":"exam2-pdf-practice-076","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #76","q":"Which describes levetiracetam?","options":["Potentiates GABA","Blocks glutamate release; given three times daily","Blocks Na⁺ channels","A pro-drug"],"answer":1,"why":"Levetiracetam blocks glutamate release; three times daily.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":76},{"id":"exam2-pdf-practice-077","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #77","q":"Which combination breaks the number-one rule of combination therapy?","options":["Levetiracetam + phenobarbital","KBr + levetiracetam","Imepitoin + KBr","Phenobarbital + imepitoin"],"answer":3,"why":"Both imepitoin and phenobarbital are GABA agonists.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":77},{"id":"exam2-pdf-practice-078","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #78","q":"Why is carbamazepine not a standard first-line long-term anticonvulsant for dogs?","options":["It irreversibly destroys canine GABA-A receptors","Species-dependent pharmacokinetics and interactions limit its routine veterinary epilepsy role; established canine drugs are generally preferred","It has no sodium-channel activity and therefore cannot affect neurons","It is the only agent that treats aggression secondary to seizures"],"answer":1,"why":"Carbamazepine is a sodium-channel modulating anticonvulsant in human medicine. Its variable/rapid clearance and interaction profile limit routine canine use; the original 'only use is seizure-associated aggression' assertion is not a defensible general rule.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":78,"sourceOriginal":{"question":"What is carbamazepine's only use in seizure management?","options":["Cluster seizures","Feline epilepsy","Status epilepticus","Preventing seizure-associated aggression"],"answer":3,"rationale":"Carbamazepine only prevents seizure-associated aggression."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-079","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #79","q":"Which describes primidone?","options":["A Na⁺ channel blocker","A direct GABA agonist","Blocks glutamate release","A pro-drug converted to phenobarbital plus PEMA; fails with liver impairment"],"answer":3,"why":"Primidone is a pro-drug for phenobarbital and PEMA.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":79},{"id":"exam2-pdf-practice-080","lecture":"Lecture 19","sourceGroup":"Lecture 19","topic":"Exam 2 PDF practice · #80","q":"What is the concern with pentobarbital euthanasia?","options":["Rendering plants refuse the carcasses, and carnivores that eat them can be poisoned","It is slow","It is not controlled","It causes pain"],"answer":0,"why":"Pentobarbital stays stable in carcasses.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":80},{"id":"exam2-pdf-practice-081","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #81","q":"What is the preferred reversal agent for xylazine?","options":["Yohimbine","Naloxone","Flumazenil","Atipamezole"],"answer":0,"why":"Yohimbine is preferred for xylazine.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":81},{"id":"exam2-pdf-practice-082","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #82","q":"What is the drug of choice for sedating a dog for allergy skin testing?","options":["Detomidine","Romifidine","Xylazine","Dexmedetomidine, dosed by body surface area"],"answer":3,"why":"Dexmedetomidine does not interfere with allergen responses; surface-area dosing.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":82},{"id":"exam2-pdf-practice-083","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #83","q":"Which describes romifidine?","options":["An equine alpha-2 agonist for colic pain with the longest duration","A swine sedative","A xylazine reversal agent","A cat anti-emetic"],"answer":0,"why":"Romifidine is equine, longest acting, for colic pain.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":83},{"id":"exam2-pdf-practice-084","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #84","q":"A veterinarian compares alpha-2 sedative protocols for horses, cattle and pigs. Which conclusion is most accurate?","options":["All species need an identical xylazine mg/kg dose","Xylazine must produce equivalent sedation in every mammalian species","Alpha-2 receptor physiology is species-sensitive; response in pigs may be variable, so protocol and drug choice must be validated for swine","No alpha-2 agonist can produce any physiologic response in pigs under any circumstances"],"answer":2,"why":"Alpha-2 agonists can have variable/limited sedative reliability in pigs, but claiming no alpha-2 agent ever works is overbroad. Species-specific evidence, dose and anesthetic protocols matter.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":84,"sourceOriginal":{"question":"Which alpha-2 agonist works in swine?","options":["Xylazine","Detomidine","None of them","Dexmedetomidine"],"answer":2,"rationale":"No alpha-2 agonist works in swine. ⚠ SOURCE REVIEW: The blanket 'no alpha-2 works in swine' claim is uncertain; verify with veterinary anesthesia references."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-085","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #85","q":"What does vatinoxan do in medetomidine + vatinoxan?","options":["Minimizes the side effects of the agonist","Reverses sedation after the procedure","Acts as an opioid","Adds sedation"],"answer":0,"why":"Vatinoxan minimizes the side effects.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":85},{"id":"exam2-pdf-practice-086","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #86","q":"What is the MOA of phenothiazines?","options":["Mu agonism","GABA agonism","Postsynaptic D2 antagonism","Alpha-2 agonism"],"answer":2,"why":"Postsynaptic D2 antagonism.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":86},{"id":"exam2-pdf-practice-087","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #87","q":"What is the genital side effect of acepromazine?","options":["Cryptorchidism","Priapism in dogs","Persistent penile prolapse in horses","Testicular hypoplasia"],"answer":2,"why":"Persistent penile prolapse in horses.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":87},{"id":"exam2-pdf-practice-088","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #88","q":"Which is NOT a use of acepromazine?","options":["Foal rejection","Laminitis","Anti-emesis","Anticonvulsant"],"answer":3,"why":"Seizures are a side effect, not a use.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":88},{"id":"exam2-pdf-practice-089","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #89","q":"What is the most useful opioid receptor antagonist?","options":["Atipamezole","Naloxone","Cyproheptadine","Flumazenil"],"answer":1,"why":"Naloxone.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":89},{"id":"exam2-pdf-practice-090","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #90","q":"A dog with epilepsy is considered for tramadol as part of a pain plan. Which safety issue is especially relevant?","options":["Tramadol is a pure kappa agonist with no serotonergic interactions","Tramadol can lower seizure threshold and has serotonergic actions; analgesic efficacy in dogs is variable","Tramadol always provides reliably strong mu-mediated analgesia in dogs","Tramadol reverses benzodiazepines without affecting pain"],"answer":1,"why":"Tramadol has weak mu effects and monoamine-reuptake actions; seizure and serotonin toxicity risks matter, particularly with other drugs. Veterinary efficacy is species-dependent and should not be assumed from human use.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":90,"sourceOriginal":{"question":"Which describes tramadol?","options":["A kappa agonist","An antagonist","A strong mu agonist that is safe in epileptics","The opioid most likely to cause seizures; effective in birds, questionable in dogs"],"answer":3,"rationale":"Tramadol lowers the seizure threshold; effective in birds."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-091","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #91","q":"Which describes butorphanol?","options":["An antagonist","A pure mu agonist","A mixed agonist-antagonist (kappa agonist, mu antagonist)","A partial mu agonist"],"answer":2,"why":"Kappa agonist, mu antagonist.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":91},{"id":"exam2-pdf-practice-092","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #92","q":"Which describes buprenorphine?","options":["A kappa agonist","A mu antagonist","A partial mu agonist and kappa antagonist","A delta agonist"],"answer":2,"why":"Partial mu agonist, kappa antagonist.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":92},{"id":"exam2-pdf-practice-093","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #93","q":"How is the abuse potential of hydrocodone cough syrup minimized?","options":["Added homatropine","Added acepromazine","It is not","Added naloxone"],"answer":0,"why":"Homatropine is added to the syrup.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":93},{"id":"exam2-pdf-practice-094","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #94","q":"Which describes wind-up?","options":["Mediated by dopamine","NMDA-driven central sensitization, prevented by pre-emptive analgesia","Treated with NSAIDs only after surgery","Caused by GABA"],"answer":1,"why":"Wind-up is NMDA-mediated central sensitization.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":94},{"id":"exam2-pdf-practice-095","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #95","q":"A cat responds behaviorally to catnip containing nepetalactone. Which explanation is the most evidence-consistent?","options":["Nepetalactone directly acts as a proven mu/kappa receptor agonist in every feline brain","Catnip response begins with olfactory chemosensory stimulation; downstream endogenous opioid signaling may contribute to responses","Catnip always causes general anesthesia by GABA-A activation","Nepetalactone acts as an alpha-2 agonist causing reliable procedural analgesia"],"answer":1,"why":"Nepetalactone is a catnip volatile detected through olfaction. An endogenous opioid pathway may participate in behavioral responses, but direct mu/kappa receptor agonism by nepetalactone is not established as a universal mechanism.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":"Revised from original instructor-derived practice for clinical accuracy; original wording and lecture answer retained in sourceOriginal. Verify lecture-specific expectations when studying.","exam":"Exam 2 · source-authored practice","sourceNumber":95,"sourceOriginal":{"question":"How does catnip work?","options":["Dopamine agonist","Mu and kappa opioid receptor agonist (nepetalactone)","Alpha-2 agonist","GABA agonist"],"answer":1,"rationale":"Nepetalactone is a mu and kappa agonist. ⚠ SOURCE REVIEW: Direct opioid-receptor agonism attributed to catnip is uncertain and should not be treated as established."},"editorialStatus":"clinical-interpretation-revision-2026-11-17"},{"id":"exam2-pdf-practice-096","lecture":"Lecture 20","sourceGroup":"Lecture 20","topic":"Exam 2 PDF practice · #96","q":"What are the three most important side effects of opioids?","options":["Hypotension, bradycardia, hyperkalemia","Respiratory depression, constipation, vomiting","Seizures, tremors, fever","Pancreatitis, hepatitis, nephritis"],"answer":1,"why":"Respiratory depression, constipation and vomiting.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Parts 2–3 · Nov 14 2026","reviewFlag":null,"exam":"Exam 2 · source-authored practice","sourceNumber":96}];
